const isIos=()=>/iphone|ipad|ipod/i.test(navigator.userAgent)||navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1;const isInstalled=()=>window.matchMedia("(display-mode: standalone)").matches||window.matchMedia("(display-mode: fullscreen)").matches||navigator.standalone===true;export function wireInstall(button,{showIosHint}={}){if(!button)return;button.hidden=true;if(isInstalled())return;const ios=isIos();let deferred=null;window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();deferred=event;button.hidden=false});if(ios&&typeof showIosHint==="function")button.hidden=false;button.addEventListener("click",async()=>{if(deferred){const prompt=deferred;deferred=null;button.disabled=true;try{await prompt.prompt();await prompt.userChoice}catch{}finally{button.disabled=false;if(!deferred)button.hidden=true}return}if(ios&&typeof showIosHint==="function")showIosHint();else button.hidden=true});window.addEventListener("appinstalled",()=>{deferred=null;button.disabled=false;button.hidden=true})}
